contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testRegression_property() public {
        // Owner (default msg.sender in setUp is address(this) as it's called from test contract)
        // We need explicit vm.prank to control sender
        address owner = address(this);

        // Step 1: Owner mints 100 tokens to another address
        address recipient = address(1);
        vm.prank(owner);
        c.mintToken(recipient, 100);

        // Step 2: Owner burns 100 tokens from their own balance (which is 0 in reference, 0 in bug)
        // Actually: initial totalSupply = 0 * 10^0 = 0, owner has 0 balance
        // Minting adds to recipient's balance, not owner's
        // So owner cannot burn (balance 0 < 100) – this will revert
        // We need owner to have enough balance to burn

        // Let's mint to owner first, then to recipient
        // Reset: fresh contract better. But we can't reset. Use new approach.
        // We'll use a different concrete scenario:
        // 1. Owner mints 1000 tokens to themselves
        // 2. Owner mint 100 tokens to recipient
        // 3. Owner burns 100 tokens
        // Reference: after burn totalSupply = 1000 + 100 - 100 = 1000
        // Bug: after bug mint, totalSupply NOT updated, so totalSupply = 1000 + 0 - 100 = 900
        // Wait, let's recalc:
        // Initial: totalSupply = 0
        // Mint to owner 1000: totalSupply becomes 1000 (reference) or 0 (bug? no, bug only misses in second mint)
        // Actually bug only deletes totalSupply update in mintToken, so first mint also buggy? 
        // The change says "Delete the totalSupply update line in mintToken function", so ALL mintToken calls don't update totalSupply.
        // So reference: first mint => totalSupply 1000, second mint => totalSupply 1100
        // Bug: first mint => totalSupply unchanged 0, second mint => totalSupply unchanged 0
        // Then owner burns 100: reference requires balanceOf[owner] >= 100, that's true (1000), totalSupply becomes 1000
        // Bug: owner's balance is 1000 (balanceOf updated), but totalSupply is 0, so burn will revert because require(balanceOf[msg.sender] >= _value) ??? No, balanceOf[msg.sender] is 1000 >= 100 true, then totalSupply -= 100 would underflow? Actually totalSupply is 0, can't subtract 100 – it will revert due to underflow in Solidity 0.8.
        // So burn reverts in bug, succeeds in reference. That's a revert difference.

        // Let's construct properly:
        // Deploy with initialSupply = 1000 so owner starts with 1000 totalSupply
        c = new C(1000, "", "");
        owner = address(this);

        // Now owner has 1000 tokens, totalSupply = 1000
        // Step: owner mints 100 to a recipient
        recipient = address(1);
        vm.prank(owner);
        c.mintToken(recipient, 100);

        // Reference: totalSupply = 1100; Bug: totalSupply = 1000
        // Step: owner burns 100 tokens
        vm.prank(owner);
        // In reference: balanceOf[owner] = 1000, totalSupply = 1100 => burn succeeds, totalSupply becomes 1000
        // In bug: totalSupply = 1000, balanceOf[owner] = 1000, after burn: totalSupply = 900, no underflow
        // Wait, both versions succeed but totalSupply differs
        // Reference: after burn totalSupply = 1100 - 100 = 1000
        // Bug: totalSupply = 1000 - 100 = 900
        c.burn(100);

        // Assert: reference totalSupply == 1000, bug totalSupply == 900
        assertTrue(c.totalSupply() == 1000, "totalSupply should be 1000 in reference");
    }
}

