import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testRegression_property() public {
        address alice = address(0x1);
        address bob = address(0x2);
        // mint to alice via owner
        c.mintToken(alice, 100);
        // alice transfers to bob
        vm.prank(alice);
        c.transfer(bob, 50);
        // owner burns some
        c.burn(10);
        // now bob (non-owner) tries to freeze alice; reference reverts, buggy succeeds
        vm.prank(bob);
        c.freezeAccount(alice, true);
        // The assertion: alice should be frozen only if the buggy version was used
        // Since we've deployed a single contract instance, we cannot test both in same test.
        // Instead we hard-code the expected correct behavior (reference) and check divergence by deploying a separate buggy version? Not allowed. So we need a single contract instance.
        // We'll interpret the task: we have ONE contract instance deployed, which is either reference or buggy. The test runs once on whichever is provided. The test must pass on reference and fail on buggy.
        // So we assert that after the above, frozenAccount[alice] is false (reference behavior). For buggy contract it would be true, causing assertion failure.
        assertTrue(!c.frozenAccount(alice));
    }
}

