import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testRegression_property() public {
        // The bug makes onlyOwner always revert; reference burn works when owner has enough balance.
        // Deploy with initialSupply=1 so owner has 1e18 balance.
        // We'll redeploy manually to have desired initial supply.
        C c2 = new C(1, "", "");
        uint256 initialSupply = 1 * 10 ** 0; // decimals=0 => 1
        // owner is deployer (address(this) in test context)
        bool successRef;
        try c2.burn(1) {
            successRef = true;
        } catch {
            successRef = false;
        }
        // Reference reverts? Actually reference: require(balanceOf[msg.sender] >= 1) is true, so no revert.
        // Buggy: modifier onlyOwner { require(false); _; } => reverts.
        // So successRef is true, successBug is false.
        // But we need to test the buggy version (c is the buggy one).
        // We'll deploy a buggy version manually? No, the test uses c which is the buggy version from the modified source.
        // The buggy version is in the source; our setup deploys with initialSupply 0, which gives owner 0 balance.
        // Doing burn(0) would trigger require(balanceOf[msg.sender] >= 0) which passes, then modifier require(false) blocks.
        // So reference (correct) would succeed, buggy would revert.
        // Let's use c (deployed with 0 supply).
        bool okRef;
        // We need to simulate reference behavior: we could deploy a separate reference contract, but we only have one contract.
        // Instead, we can just compare the revert behavior of c.burn(0) vs what the reference would do.
        // Since the reference would succeed (balanceOf[owner]=0, require(0>=0) true, no other reverts), but c reverts.
        bool okActual;
        try c.burn(0) {
            okActual = true;
        } catch {
            okActual = false;
        }
        // In reference, okActual would be true; in buggy, false.
        assertTrue(okActual == false); // buggy reverts, so okActual is false; but this assertion would pass on buggy and fail on reference.
        // Actually we want assertion that reference passes and buggy fails. So assertTrue(okActual == true) would pass on reference, fail on buggy.
        // Let's assertTrue(okActual == true) — reference would have true, buggy has false.
        // But since we are testing the buggy contract, we need the test to FAIL on buggy. So we assert the reference behavior.
        // We cannot directly test reference, but we can reason: in this scenario, reference would allow burn(0) without revert.
        // So we assert that the call did NOT revert (i.e., okActual == true). Buggy will fail.
        assertTrue(okActual == true);
    }
}

